<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\DTO\Exam\ExamSessionDTO; use Inc\Repositories\WPDBRepositories\ExamSessionRepository; class ExamSessionService { private ExamSessionRepository $repo; public function __construct( ?ExamSessionRepository $repo = null ) { $this->repo = $repo ?? new ExamSessionRepository(); } public function createSession( int $eventId, int $assessmentId, string $scheduledAt, string $plannedEndAt, int $roomId, int $capacity, int $responsibleUserId ): int { return $this->repo->insert( [ 'event_id' => $eventId, 'assessment_id' => $assessmentId, 'scheduled_at' => $scheduledAt, 'planned_end_at' => $plannedEndAt, 'room_id' => $roomId, 'capacity' => $capacity, 'responsible_user_id' => $responsibleUserId, 'status' => 'open', 'created_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ), ] ); } public function getSession( int $sessionId ): ?ExamSessionDTO { return $this->repo->find( $sessionId ); } public function getEventSessions( int $eventId ): array { return $this->repo->findByEvent( $eventId ); } public function updateOccupied( int $sessionId, int $newCount ): bool { return $this->repo->update( $sessionId, [ 'occupied_count' => $newCount, 'updated_at' => current_time( 'mysql', true ), ] ); } public function cancelSession( int $sessionId, string $reason ): bool { return $this->repo->update( $sessionId, [ 'status' => 'cancelled', 'cancel_reason' => $reason, 'updated_at' => current_time( 'mysql', true ), ] ); } public function hasCapacity( int $sessionId ): bool { $session = $this->getSession( $sessionId ); return $session ? $session->occupiedCount < $session->capacity : false; } }
